// The reviewer has no tools. Grants refer to this immutable batch, not to
// actions generated by the reviewer. A missing or extra grant rejects it all.
export async function assessRoute(planner,turn,snap,plan){
  const steps=[...plan.actions];
  if(plan.workControl)steps.push({type:'work_control',...plan.workControl});
  if(!steps.length)return null;
  const proposals=steps.map((step,index)=>{
    const {type,...effect}=step;
    return {...effect,index,kind:type};
  });
  const input={phase:'routeAuthority',currentUser:turn.text,history:snap.history,now:snap.now,timeZone:snap.timeZone,
    attachedSession:snap.attachedSession,activeWork:snap.activeWork,cards:snap.cards,follow:snap.follow,
    devices:snap.workers?.map(({deviceId,deviceName,target,agentName,deviceAliases,aliases})=>({deviceId,deviceName,target,agentName,deviceAliases,aliases})),
    sessions:snap.sessions?.map(({id,machine,target,title})=>({id,machine,target,title})),
    tasks:snap.tasks?.map(({id,target,title})=>({id,target,title})),
    preferences:snap.preferences?.filter(p=>proposals.some(a=>a.kind==='forget'&&a.id===p.id||a.kind==='remember'&&a.key===p.key)).map(({id,key,scope,text})=>({id,key,scope,text})),
    commitments:snap.commitments?.filter(c=>proposals.some(a=>a.kind==='close'&&a.id===c.id)).map(({id,text,status})=>({id,text,status})),
    criteria:plan.criteria,proposals};
  const review=await planner.plan(input);
  const receipts=review.actions??[];
  const seen=new Set();
  const valid=receipts.length===proposals.length&&receipts.every(r=>{
    const p=Number.isSafeInteger(r?.index)&&proposals[r.index];
    if(!p||r.type!=='allow_effect'||seen.has(p.index)||r.kind!==p.kind||
      (p.target&&r.target!==p.target)||typeof r.evidence!=='string'||!r.evidence.trim()||!turn.text.includes(r.evidence))return false;
    seen.add(p.index);return true;
  });
  if(valid)return null;
  const reason=typeof review.reply==='string'?review.reply.trim().slice(0,500):'';
  return {message:reason||'我没能核实这次请求的对象和操作范围，尚未执行。',
    replan:receipts.length===0&&review.directBasis==='replan'&&Boolean(reason)};
}
export async function routeDecision(planner,turn,snap,plan){
  return (await assessRoute(planner,turn,snap,plan))?.message??null;
}
